-- The closed category tree the post-tags pass tags against (scfd-entity-model #6): IAB Content Taxonomy 3.1's 34
-- subject domains and every descendant, keyed by our own slug path (`style-fashion/womens-fashion`) with English
-- labels; our own nodes join later as extension rows. Events, Genres and Sensitive Topics are not subjects and stay out.
-- Source: IAB Tech Lab Content Taxonomy 3.1, CC BY 3.0 (https://iabtechlab.com/standards/content-taxonomy/). The seed
-- below is generated once by tools/iab-taxonomy-seed.py from the 3.1 TSV; the TSV is not committed.
CREATE TABLE IF NOT EXISTS harvest_taxonomy_nodes (
    key        text     NOT NULL,
    iab_id     text     NULL,
    parent_key text     NULL,
    tier       smallint NOT NULL,
    label      text     NOT NULL,
    extension  boolean  NOT NULL DEFAULT false,
    active     boolean  NOT NULL DEFAULT true,

    CONSTRAINT pk_harvest_taxonomy_nodes PRIMARY KEY (key),
    CONSTRAINT fk_harvest_taxonomy_nodes_parent FOREIGN KEY (parent_key) REFERENCES harvest_taxonomy_nodes (key),
    CONSTRAINT ck_harvest_taxonomy_nodes_key CHECK (key ~ '^[a-z0-9]+(-[a-z0-9]+)*(/[a-z0-9]+(-[a-z0-9]+)*)*$'),
    CONSTRAINT ck_harvest_taxonomy_nodes_parent CHECK (parent_key IS NULL OR left(key, length(parent_key) + 1) = parent_key || '/'),
    CONSTRAINT ck_harvest_taxonomy_nodes_tier CHECK (tier BETWEEN 1 AND 6 AND (tier = 1) = (parent_key IS NULL)),
    CONSTRAINT ck_harvest_taxonomy_nodes_source CHECK (extension OR iab_id IS NOT NULL),
    CONSTRAINT ck_harvest_taxonomy_nodes_label CHECK (length(label) BETWEEN 1 AND 200)
);

CREATE UNIQUE INDEX IF NOT EXISTS ux_harvest_taxonomy_nodes_iab ON harvest_taxonomy_nodes (iab_id) WHERE iab_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS ix_harvest_taxonomy_nodes_parent ON harvest_taxonomy_nodes (parent_key);

-- 657 nodes: 34 domains and their IAB descendants.
ON CONFLICT (key) DO NOTHING;
